<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';require_once __DIR__.'/../config/governance.php';
$admin=require_permission($pdo,'legal.manage');$pageTitle='Rechtsdokumente';$error='';$selectedId=is_string($_GET['id']??null)?(int)$_GET['id']:0;
$values=['code'=>'','version'=>'1.0','language'=>'de','title'=>'','body'=>''];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){require_csrf();try{$action=post_string('action');if($action==='create'){foreach($values as $key=>$_)$values[$key]=post_string($key,$key==='body'?200000:500);$selectedId=legal_create($pdo,(int)$admin['id'],$values['code'],$values['version'],$values['language'],$values['title'],$values['body']);redirect('/admin/legal.php?id='.$selectedId);}elseif($action==='approve'){$selectedId=(int)post_string('document_id');$checks=[];for($i=1;$i<=5;$i++)$checks[]=post_string('check_'.$i);legal_approve($pdo,(int)$admin['id'],$selectedId,post_string('reviewer',200),post_string('effective_at',10),$checks);redirect('/admin/legal.php?id='.$selectedId);}else throw new InvalidArgumentException('Ungültige Aktion.');}catch(InvalidArgumentException|DomainException $e){http_response_code(422);$error=$e->getMessage();}catch(PDOException $e){if($e->getCode()!=='23000')throw$e;http_response_code(409);$error='Diese Dokumentkennung, Version und Sprache existieren bereits. Bitte eine neue Version anlegen.';}}
$q=$pdo->prepare('SELECT * FROM market_legal_documents WHERE id=?');$q->execute([$selectedId]);$selected=$q->fetch();$documents=$pdo->query('SELECT id,document_code,version,language,title,status,content_hash,effective_at,reviewer_name FROM market_legal_documents ORDER BY document_code,language,id DESC LIMIT 500')->fetchAll();
include __DIR__.'/../includes/header.php';?>
<main class="container admin-page"><div class="page-heading"><p class="eyebrow">Versioniert und nachvollziehbar</p><h1>Rechtstexte verwalten.</h1><p>Entwürfe sind nicht anwaltlich freigegeben. Veröffentlichte Inhalte und Zustimmungen bleiben an ihre unveränderliche Version gebunden.</p></div><div class="admin-layout"><?php include __DIR__.'/../includes/admin-nav.php';?><div class="admin-content"><?php if($error):?><p class="notice error"><?=h($error)?></p><?php endif;?>
<?php if($selected):?><section class="panel"><h2><?=h($selected['title'])?> · <?=h($selected['version'])?> / <?=h($selected['language'])?></h2><p>Status <?=h($selected['status'])?> · SHA-256 <code><?=h($selected['content_hash'])?></code></p><details><summary>Gespeicherten vollständigen Inhalt lesen</summary><div style="white-space:pre-wrap;overflow-wrap:anywhere"><?=h($selected['body_text'])?></div></details>
<?php if($selected['status']==='draft'):?><h3>Dokumentierte fachliche Freigabe</h3><p>Diese Checkliste ersetzt keine tatsächliche Prüfung. Pflichtfelder müssen durch fachlich richtige Betreiberangaben ersetzt sein. Eine neue Fassung benötigt eine neue Version; bestehende Vertragsnachweise werden nicht rückwirkend umgeschrieben.</p><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="approve"><input type="hidden" name="document_id" value="<?=(int)$selected['id']?>"><label class="field">Verantwortliche fachliche Prüfstelle<input name="reviewer" minlength="5" maxlength="200" required></label><label class="field">Gültig ab<input type="date" name="effective_at" required></label>
<?php foreach(['Betreiberidentität, Kontakt- und Pflichtangaben sind vollständig und richtig.','Geschäftsmodell, freigegebene Länder und tatsächliche Funktionen stimmen mit dem Dokument überein.','Verbraucherrechte, Haftungsgrenzen, Widerruf und Gebühren wurden fachlich geprüft.','Datenschutz, Aufbewahrung, Melde-/Beschwerdeverfahren und Zahlungsanbieterbedingungen wurden geprüft.','Die angegebene Fachprüfung ist tatsächlich erfolgt; notwendige erneute Zustimmungen wurden organisatorisch festgelegt.'] as $i=>$text):?><label><input type="checkbox" name="check_<?=$i+1?>" value="1" required> <?=h($text)?></label><?php endforeach;?><button class="button" type="submit">Fachliche Freigabe dokumentieren</button></form><?php else:?><p>Freigegeben durch <?=h($selected['reviewer_name'])?> · gültig ab <?=h($selected['effective_at'])?> UTC. Die globale Veröffentlichungsfreigabe wird separat geprüft.</p><?php endif;?></section><?php endif;?>
<section class="panel"><h2>Neue unveränderliche Fassung anlegen</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="create"><label class="field">Dokumentkennung<input name="code" pattern="[a-z0-9-]{2,80}" value="<?=h($values['code'])?>" required></label><label class="field">Version<input name="version" pattern="[a-zA-Z0-9.-]{1,30}" value="<?=h($values['version'])?>" required></label><label class="field">Sprache<input name="language" pattern="[a-z]{2}(-[A-Z]{2})?" value="<?=h($values['language'])?>" required></label><label class="field">Titel<input name="title" maxlength="200" value="<?=h($values['title'])?>" required></label><label class="field full-width">Vollständiger Entwurf<textarea name="body" rows="16" minlength="200" maxlength="200000" required><?=h($values['body'])?></textarea></label><button class="button" type="submit">Entwurf speichern</button></form></section>
<section class="panel"><h2>Dokumentversionen</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Dokument</th><th>Version</th><th>Sprache</th><th>Status</th></tr></thead><tbody><?php foreach($documents as $doc):?><tr><td><a href="?id=<?=(int)$doc['id']?>"><?=h($doc['title'])?></a></td><td><?=h($doc['version'])?></td><td><?=h($doc['language'])?></td><td><?=h($doc['status'])?></td></tr><?php endforeach;?></tbody></table></div></section></div></div></main><?php include __DIR__.'/../includes/footer.php';?>
